static const size_t n_euler = sizeof(euler_factors) / sizeof(euler_factors[0]);

int main(int argc, char** argv) {
  if(argc!=4)
    {
      printf("Usage:- %s <target prec> <num Eulers to use> <log_2 B>.\n",argv[0]);
      return 0;
    }
  Lerror_t ecode = 0;
  double mus[2] = {0, 1};
  Lparams_t params;
  params.big_B = (uint64_t) 1 << atoi(argv[3]); // B will be this/degree
  params.degree = 2;
  double t0=(double)params.big_B/(double)params.degree/16.0;
  params.conductor = 399998;
  params.normalisation = 0.5;
  params.mus = mus;
  params.target_prec = atol(argv[1]);//DEFAULT_TARGET_PREC;
  params.wprec = 0;   // 0 => library derives working precision
  params.gprec = 0;   // 0 => library derives G precision
  params.self_dual = YES;
  params.rank = 1;
  params.cache_dir = NULL;

  Lfunc_t L = Lfunc_init_advanced(&params, &ecode);
  fprint_errors(stdout,ecode);
  assert(!fatal_error(ecode));

  uint64_t nmax = Lfunc_nmax(L);
  // The table lists every prime from 2 contiguously, so if its last prime
  // reaches nmax then every prime p <= nmax is supplied and the Dirichlet
  // series is NOT truncated early (an early truncation would itself perturb the
  // zeros / the Turing count and fail the test for the wrong reason).
  //assert(euler_factors[n_euler - 1].p >= nmax);

  printf("glfunc wants Euler factors to p=%ld\n",nmax);

  int64_t num_eulers=atol(argv[2]);
  uint64_t last_p = euler_factors[n_euler-1].p;

  if(num_eulers>last_p)
    {
      printf("Don't have enough Euler factors %lu to meet request %lu. Ignoring.\n",last_p,num_eulers);
      num_eulers=last_p;
    }
  
  if(num_eulers>nmax)
    printf("Available/requested Eulers %lu exceed nmax %lu, ignoring.\n",num_eulers,nmax);
  else
    {
      printf("Reducing nmax from %lu to %lu.\n",nmax,num_eulers);
      Lfunc_reduce_nmax(L,num_eulers);
      ecode|=ERR_INSUFF_EULER;
    }

  
  acb_poly_t poly;
  acb_poly_init(poly);
  for (size_t i = 0; i < n_euler; i++) {
    uint64_t p = euler_factors[i].p;
    if (p > nmax)
      break;
    acb_poly_zero(poly);
    for (int j = 0; j < 3; j++) {
      acb_poly_set_coeff_si(poly, j, euler_factors[i].c[j]);
    }
    Lfunc_use_lpoly(L, p, poly);
  }
  acb_poly_clear(poly);

  ecode |= Lfunc_compute(L);


#ifdef COMPUTE_ZEROS
  arb_srcptr zeros = Lfunc_zeros(L,0);
  printf("First zero is at ");arb_printd(zeros,20);printf("\n");
  uint64_t z_ptr=0;
  while(!arb_is_zero(zeros+z_ptr)) z_ptr++;
  printf("Last zero is at ");arb_printd(zeros+z_ptr-1,20);printf("\n");
#endif

 
  acb_t sv;
  acb_init(sv);
  ecode |= Lfunc_special_value(sv,L,1.5,0.0);
  printf("L(1.5)=");acb_printd(sv,20);printf("\n");
  
  Lfunc_clear(L);
  fprint_errors(stdout,ecode);

  
  return 0; // all assertions passed
}
